from lib import *
S = SS('u123')
R = J('u123'); E = {k: sz for k, ext, sz in R['emit']}; n = R['nphases']; cm = R['cmp']; d, r_ = cm['debug(opt-level=0)'], cm['release(-O)']
steps = [
    step(f"rustc 一次编译的各种产物(--emit=…,一个 20 行的小程序):dep-info {E['dep-info']} 字节、metadata(.rmeta,给别的 crate 做类型检查用){E['metadata']:,} 字节、mir {E['mir']:,} 字节、llvm-ir {E['llvm-ir']:,} 字节、asm {E['asm']:,} 字节、obj {E['obj']:,} 字节。MIR 之后体积一路膨胀:LLVM IR 是 MIR 文本的约 {E['llvm-ir'] // E['mir']} 倍(debuginfo 关闭)。", t=tl(S(1)), done=lidx(S(1), 'dep-info', 'metadata', 'mir', 'llvm-ir', 'asm', 'obj'), b=bars([['mir', E['mir'], f"{E['mir']:,}"], ['obj', E['obj'], f"{E['obj']:,}"], ['asm', E['asm'], f"{E['asm']:,}"], ['llvm-ir', E['llvm-ir'], f"{E['llvm-ir']:,}"]], E['llvm-ir'], done=[0, 1, 2, 3]), kv=KV([['mir', f"{E['mir']:,} B"], ['llvm-ir', f"{E['llvm-ir']:,} B"], ['obj', f"{E['obj']:,} B"]], ['llvm-ir'])),
    step(f"-Z time-passes(RUSTC_BOOTSTRAP=1)给出 {n} 个计时条目,整个编译约 {R['total'][0].split(';')[0].replace('time:', '').strip()} 秒。耗时最长的是链接相关(link_binary / run_linker 约 0.05 s)和 LLVM(LLVM_passes 0.019 s),类型检查 type_check_crate 约 0.006 s。对这个小程序,大头不是前端而是后端与链接。", t=tl(S(2)), done=lidx(S(2), '共 ', '0.101 s  total', 'link', 'LLVM_passes', 'type_check_crate'), kv=KV([['链接', '约 0.05 s'], ['LLVM_passes', '约 0.02 s'], ['type_check_crate', '约 0.006 s']], ['链接'])),
    step("条目按出现顺序正好就是编译流水线:parse_crate(解析)→ expand_crate / macro_expand_crate(宏展开)→ resolve_crate(名字解析)→ coherence_checking → type_check_crate(类型检查)→ MIR_borrow_checking(借用检查)→ monomorphization_collector_graph_walk(收集要生成的单态化实例)→ codegen_to_LLVM_IR → LLVM_passes → run_linker(链接)。条目是嵌套的(如 total 包住全部),不能直接相加。", t=tl(S(3)), done=lidx(S(3), 'parse_crate', 'expand_crate', 'resolve_crate', 'type_check_crate', 'MIR_borrow_checking', 'monomorphization_collector_graph_walk', 'codegen_to_LLVM_IR', 'LLVM_passes', 'run_linker'), kv=KV([['前端', 'parse → expand → resolve → typeck → borrowck'], ['后端', 'mono → LLVM IR → LLVM passes → link']], ['后端'])),
    step(f"debug 与 release 的差别集中在 LLVM:debug(opt-level=0)total {d['total']} s、LLVM_passes {d['LLVM_passes']} s;release(-O)total {r_['total']} s、LLVM_passes {r_['LLVM_passes']} s(约 {r_['LLVM_passes'] / d['LLVM_passes']:.1f} 倍);而 type_check_crate({d['type_check_crate']} s 对 {r_['type_check_crate']} s)与 link_binary({d['link_binary']} s 对 {r_['link_binary']} s)基本不变。优化只发生在 LLVM 阶段。", t=tl(S(4)), done=lidx(S(4), 'debug', 'release'), b=bars([['debug LLVM_passes', d['LLVM_passes'], f"{d['LLVM_passes']} s"], ['release LLVM_passes', r_['LLVM_passes'], f"{r_['LLVM_passes']} s"]], r_['LLVM_passes'], cur=[1], done=[0]), kv=KV([['debug', f"total {d['total']} s,LLVM {d['LLVM_passes']} s"], ['release', f"total {r_['total']} s,LLVM {r_['LLVM_passes']} s"]], ['release'])),
]
A = mkart('u123', 123, 'Rust,编译,rustc,编译阶段,真实验证,动画演示',
    f'用 --emit 与 -Z time-passes 看 rustc 的编译阶段:各种产物的大小(llvm-ir {E["llvm-ir"]:,} 字节对 mir {E["mir"]:,} 字节);{n} 个计时条目按序就是 parse → 宏展开 → 名字解析 → 类型检查 → 借用检查 → 单态化收集 → LLVM IR → LLVM passes → 链接;debug 与 release 的差别集中在 LLVM_passes({d["LLVM_passes"]} s 对 {r_["LLVM_passes"]} s)。',
    'Rust 编译到底分几步?每一步产出什么?时间花在哪里?这篇不画示意图,而是让 rustc 自己报告:各 --emit 产物、time-passes 的全部计时条目,以及 debug 与 release 的对比。',
    [(f'{n} 个', 'time-passes 报告的计时条目数(嵌套的)'), (f'{E["llvm-ir"] // E["mir"]}×', 'LLVM IR 文本体积对 MIR 文本体积的倍数'), (f'{r_["LLVM_passes"] / d["LLVM_passes"]:.1f}×', 'release 的 LLVM_passes 耗时对 debug 的倍数')],
    [('编译会产出哪些东西', '<p>MIR 见<a href="rust-mir.html">MIR 是什么</a>;LLVM IR 见<a href="rust-llvm-ir-optimization.html">LLVM IR 与优化</a>。</p>'), ('各阶段耗时', '<p>time-passes 使用 RUSTC_BOOTSTRAP=1;只测了一个 20 行的小程序,大型 crate 的耗时分布(类型检查、借用检查占比更大)没有测。</p>'), ('流水线的顺序', None), ('debug 与 release', '<p>更多构建差异见<a href="rust-debug-vs-release.html">Debug 与 Release 构建差异</a>。</p>')],
    steps, [ENV_U + '。time-passes 为 -Z 选项,需要 RUSTC_BOOTSTRAP=1', '没有验证:大型 crate(如 tokio)的阶段耗时分布、增量编译对各阶段的影响、并行前端(-Z threads)、链接器替换(lld / mold)的耗时变化、cargo --timings 的输出'], '编译阶段')
